    "content": "Temel Mali Ve Tali Tablolar Mali Analizin Yapılmasının Amacı, Kavramı Ve Mahiyeti İşletmelerde Kullanılan Mali Tablolar Ve İlkelerinin Açıklanması Mali Tabloların Belirlenen Standartlara Göre Düzenlenmesi Mali Analiz Teknikleri Karşılaştırmalı Tablolar Analizi Dikey Yüzde Yöntemi Yüzde Yöntemi ile AnalizTrend (Eğilim) Yüzdeleri Yöntemi Oran Analizi Yöntemi Fon Akım Tablosu Ve Nakit Akım Tablosu Net İşletme Sermayesi Değişim Tablosu Proforma Tablosu Ve Konsolide Tablolar Mali Analiz Tekniklerinden Çıkan Sonuçların Yorumlanması Ve Önerilen Tedbirler Yönetimin Mali Analiz Bilgilerinden Nasıl Yararlanacağı",
