    "purpose": "Bu dersin amacı, öğrencilerin hizmet pazarlaması alanındaki ileri düzey teorik yaklaşımları, güncel araştırmaları ve uygulama örneklerini analiz edebilmesini sağlamaktır. Öğrenciler, hizmet odaklı işletmelerin stratejik pazarlama kararlarını değerlendirecek, hizmet kalitesi, müşteri deneyimi, teknoloji ve yenilik odaklı hizmet tasarımı gibi konularda akademik ve uygulamalı yetkinlik kazanacaktır.",
    "content": "Bu ders, hizmet pazarlamasının temel ve ileri düzey kavramlarını; hizmet kalitesi, müşteri deneyimi, hizmet tasarımı, teknoloji ve dijitalleşme, tüketici davranışları, ilişki yönetimi ve çağdaş hizmet pazarlaması stratejilerini kapsar. Ders kapsamında her hafta bir akademik makale analiz edilerek seminer tartışmaları yürütülür.",
    "methods": "Anlatım, tartışma, vaka analizi, makale incelemesi, öğrenci sunumları, araştırma önerisi hazırlama, sınıf içi tartışmalar, eleştirel düşünme uygulamaları, seminer çalışmaları.",
