    "content": "Olasılık, şans değişkenleri, olasılık fonksiyonları, beklenen değer ve moment çıkaran fonksiyonu, iki veya çok boyutlu şans değişkenleri ve olasılık fonksiyonları, kesikli olasılık dağılışları ve sürekli olasılık dağılışları, binom ve poisson dağılışına normal yaklaşık, merkezi limit teoremi.",
