    "purpose": "Matematiğin temel prensiplerini, fonksiyonları, türev ve integral kurallarını, grafik çizimlerini, doğrusal denklem sistemlerini, matrisleri, determinantı, matris uygulamalarını tanıtmak, öğretmek, işletme ve ekonomi açısından uygulanmasını sağlamak.",
    "content": "Mantık, kümeler, sayılar (doğal, tam, rasyonel ve reel). Bağıntı, fonksiyon ve işlem, çarpanlara ayırma, polinomlar ve grafik çizimi, logaritma ve üstel fonksiyonlar, limit, türev ve integral, diziler, türev alma kuralları, fonksiyonların değişimlerinin ve grafiklerinin incelenmesi, lineer fonksiyonlar, matrisler, determinantlar, matris ve determinantların uygulanması.",
    "methods": "Kuramsal anlatım, problem çözme, bilimsel kaynak incelemesi ve işletme bulgularının tartışılması.",
