    "purpose": "Bu dersin amacı, işletmelerde maliyetlerin oluşum sürecini, maliyetlerin sınıflandırılmasını ve maliyet bilgilerini kullanarak karar verme süreçlerini öğretmektir. Öğrencilerden, maliyet muhasebesi verilerini analiz ederek üretim maliyetlerini kontrol altına alma, verimliliği artırma ve yönetim kararlarına katkı sağlama becerisi kazanmaları beklenmektedir.",
    "content": "Maliyet kavramı ve türleri, maliyet sistemleri, gider yerleri ve gider dağıtımı, mamul maliyetinin hesaplanması, standart maliyetleme, sipariş ve safha maliyet sistemi, maliyet-hacim-kâr analizi, değişken ve sabit maliyet analizi, genel üretim giderleri, maliyet kontrolü, bütçeleme ve karar verme sürecinde maliyet bilgileri.",
    "methods": "Anlatım, Alıştırma & Problem Çözme, Soru & Cevap",
