    "purpose": "Bu dersin temel amacı finansal piyasa ve araçları tanıtmak, finansal kurumların çalışma prensiplerini öğretmek, temel kavramlar ile finansal piyasa ve kurumların temel amaçlarına ulaşabilmek için hangi varsayımlar ve kısıtlamalar altında hareket edilmesi gerektiğinden bahsetmek.",
    "content": "Finansal Varlıklar, Finansal Piyasalar, Sermaye Piyasası AraçlarıSermaye Piyasasının Getirdiği Yenilikler, Sermaye Piyasası Faaliyetleri , Türkiye'de Sermaye Piyasası ve Sermaye Piyasası Kanununun Kapsamı, Sermaye Piyasası Faaliyetleri, AB Entegrasyon Sürecindeki Gelişmeler",
    "methods": "Kuramsal anlatım, problem çözme, bilimsel kaynak incelemesi ve işletme bulgularının tartışılması.",
