    "name": "PAZARLAMADA GÜNCEL KONULAR",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Bahar",
    "instructor": "Dr. Öğr. Üyesi MEHMET FATİH AÇAR",
    "purpose": "Türkiye’de ve dünyada pazarlama alanındaki yeni yaklaşımları ve güncel konuları ele alarak öğrencilerin pazarlama alanındaki güncel bilgilerini arttırmayı amaçlar.",
    "content": "Bu ders, pazarlama disiplininde son yıllarda ortaya çıkan güncel yaklaşımları ve yenilikçi uygulamaları kapsamlı biçimde ele alır. Ders kapsamında; hikâye pazarlaması, ekolojik (yeşil) pazarlama, sağlık hizmetlerinde pazarlama, gerilla pazarlama, korku pazarlaması, fijital (fiziksel ve dijital entegrasyon) pazarlama, sosyal medya pazarlaması, alfa kuşağı pazarlaması, bütünleşik kanallı (omni-channel) pazarlama, influencer pazarlama, siyasal pazarlama, girişimci pazarlama ve avatar pazarlaması gibi konular incelenir. Her bir konu, pazarlamanın değişen doğası, dijitalleşme süreci, tüketici davranışlarındaki dönüşüm ve etik-sürdürülebilirlik perspektifleriyle ilişkilendirilir. Ders süresince vaka analizleri, güncel örnekler ve grup çalışmaları aracılığıyla teorik bilgilerin uygulamaya dönüştürülmesi hedeflenir.",
    "methods": "Anlatım, Ters-yüz sınıf.",
    "resources": "Dersin gerçek OBS kaynakları; güncel iktisat literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
