    "content": "Perakendeciliğe giriş, perakendeci türleri, perakende pazar stratejileri, perakende mağaza kuruluş yeri, ürün yönetimi, perakende fiyatlama ve iletişim karması, mağaza yönetimi ve görsel sunum, müşteri hizmetleri.",
