    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Bahar",
    "instructor": "Prof. Dr. MUTLU YÜKSEL AVCILAR",
    "purpose": "Bu dersin amacı, işletmelerin karar alma süreçlerinde bilgiye dayalı yönetim anlayışını destekleyen pazarlama araştırması sürecini öğretmektir. Öğrenciler; araştırma problemini tanımlama, araştırma tasarımı oluşturma, örnekleme, veri toplama teknikleri, veri analizi ve sonuç raporlama konularında bilgi ve beceri kazanırlar. Ayrıca, istatistiksel analizlerin pazarlama kararlarına nasıl dönüştürüleceğini öğrenirler.",
    "content": "Pazarlama araştırmasının tanımı, önemi ve kapsamı; araştırma süreci aşamaları; araştırma probleminin belirlenmesi; veri toplama yöntemleri (anket, gözlem, odak grup vb.); örnekleme türleri; ölçme ve ölçek geliştirme; anket tasarımı; veri giriş ve düzenleme; istatistiksel analizlerin (tanımlayıcı istatistikler, korelasyon, regresyon, faktör analizi vb.) pazarlama kararlarına uygulanması; araştırma raporunun hazırlanmasını kapsamaktadır.",
    "methods": "Anlatım, Uygulama / (SPSS / Excel)",
    "resources": "Dersin gerçek OBS kaynakları; güncel iktisat literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
    "sdgs": [
      "8",
      "9",
      "12"
    ],
    "outcomes": [
      "Pazarlama araştırması kapsamındaki ileri kuramsal bilgileri analiz eder.",
      "Pazarlama yönetimi yaklaşımlarını karşılaştırır.",
      "Pazarlama araştırması kapsamında uygun iktisadi modeli uygular.",
      "Pazarlama araştırması bulgularını ekonomik ve toplumsal etkileriyle değerlendirir.",
      "Pazarlama araştırması alanındaki kanıtlara dayalı politika çıkarımları geliştirir."
    ],
    "weeklyTopics": [
      "Pazarlama araştırmasının tanımı, amacı ve önemi",
      "Pazarlama araştırması süreci, problem tanımlama ve hatalar",
      "Pazarlama Bilgi Sistemi ve Etik",
      "Araştırma türleri: Keşifsel, tanımlayıcı, nedensel",
      "Nitel araştırmalar: yöntemler, görüşme ve gözlem teknikleri",
      "Veri toplama yöntemleri: Birincil ve ikincil veriler",
      "Ölçme, ölçek geliştirme ve anket hazırlama",
      "Örnekleme süreci ve örnekleme türleri",
      "Veri toplama süreci, saha çalışması ve araştırma etiği",
      "Veri girişi, düzeltme ve kodlama işlemleri",
      "Tanımlayıcı istatistikler ve veri analizi",
      "Korelasyon ve regresyon analizleri",
      "Faktör analizi, güvenilirlik analizi ve geçerlilik değerlendirmesi",
      "Bulguların yorumlanması ve araştırma raporunun hazırlanması",
      "Pazarlama araştırması: kapsam ve temel kavramlar"
    ],
